sys_ux_data_broker_transform.script:
(function() {
    // Input data (this will come from the data broker)
    var input = data;  // In Data Broker, the input data is typically available as `data`

    // Define the output object
    var kpiValues = {
        'grouped_publishers': []
    };

    // Add the buttons data to the kpiValues object
    var buttonsData = [
        { "id": "button1", "label": "8.33%", "value": 8.33 },
        { "id": "button2", "label": "12.5%", "value": 12.5 },
        { "id": "button3", "label": "16.67%", "value": 16.67 },
        { "id": "button4", "label": "20%", "value": 20 },
        { "id": "button5", "label": "25%", "value": 25 },
        { "id": "button6", "label": "33.33%", "value": 33.33 }
    ];

    // Transform input data into the expected output format
    kpiValues.grouped_publishers = buttonsData.map(function(button) {
        return {
            id: button.id,
            label: button.label,
            value: button.value
        };
    });

    // Return the transformed data
    return kpiValues;
})();
